  AMODELX s mo ->
  AMODELX (mkAst (hit_state (a_st s) c cnt rest ch) (a_thr s) (a_ctx s) (a_fsb s) (a_L s) (a_S s) (a_Zr s) (a_AL s) (a_top s) (a_bot s)) mo.
